      "name": "GENERATED_ARTIFACT_VALIDATED",
      "definition": "A subsequent execution step performs checks to determine whether an artifact produced by an earlier generation step satisfies specified constraints or requirements.",
      "source_description": "An artifact produced by an earlier generation step.",
      "target_description": "A later validation step that checks that artifact against the required constraints."
    },
    {
      "name": "SUCCESSFUL_VALIDATION_ENABLES_COMPLETION",
      "definition": "Positive results from a verification step confirming that all requirements are satisfied are used as the basis for the agent's decision to finalize and mark the task complete.",
      "source_description": "The outcome of a verification step indicating that the required constraints are satisfied.",
      "target_description": "The agent's decision or action to finalize and complete the task."
    },
    {
      "name": "ASSEMBLES_COMPOSITE_FROM_RETRIEVED_COMPONENTS",
      "definition": "An execution step constructs a combined artifact by assembling multiple previously retrieved component sequences or data elements into a single ordered composite.",
      "source_description": "Previously retrieved component sequences or data elements to be combined.",
      "target_description": "An assembly step that combines those components into a single ordered composite artifact."
    }
  ]
}

